// Typed, lazy loaders for the Developer's Cut content (generated by tools/content/devcut.ts).
// Vite code-splits the JSON; nothing loads until the Dev Cut or the Studio is opened.

export type DcSource = 'original' | 'reconstructed';
export type DcProvenance = 'original' | 'original-data' | 'adapted' | 'reconstruction';

export interface DcText {
  id: string;
  text: string;
  source: DcSource;
  provenance: DcProvenance;
  /** true when the original exists only as audio/art and this is its transcript */
  transcribed?: boolean;
  cast?: { movie: string; castId: number };
  role?: string;
  basis?: string[];
  signature?: string;
  audio?: string;
  asset?: string;
}
export interface DcRecord {
  id: string;
  title: string;
  line: string;
  source: DcSource;
  /** a Remastered music cue id (public/assets/audio/music/manifest.json, played by src/audio) */
  music?: string;
  /** or a file under public/ (assets/devcut/...) */
  audio?: string;
  /** shown only once the finale has been heard on this profile */
  requires?: 'finaleHeard';
}
export interface DevcutContent {
  schema: string;
  texts: Record<string, DcText>;
  signatures: Record<string, { asset: string; reads: string; use: string; provenance: DcProvenance }>;
  portraits: Record<string, { asset: string; who: string; provenance: DcProvenance }>;
  audio: Record<string, unknown> & {
    birth: { asset: string };
    finale: { shipped: { asset: string }; newer: { asset: string } };
  };
  video: { macloan: { asset: string } };
  ui: {
    gramophone: { card: string; slider: string; records: DcRecord[] };
    woodenFence: { page: string; price: number };
    [k: string]: unknown;
  };
  freight: { destinations: Record<string, { label: string; transport: string; source: DcSource }>; clerk: string };
  items: { id: string; kind: string; title: string; trigger?: string; spec?: string; reconstruction?: { needed: boolean } }[];
}

export interface StudioCard {
  id: string;
  title: string;
  caption: string;
  source: DcSource;
  facts: { text: string; cite: string }[];
  assets?: string[];
  badge?: DcProvenance;
  redacted?: boolean;
}
export interface StudioArt {
  id: string;
  title: string;
  caption: string;
  source: DcSource;
  badge: DcProvenance;
  asset: string;
  path: string;
}
export interface StudioSound {
  id: string;
  title: string;
  caption: string;
  source: DcSource;
  asset: string;
  path: string;
  audited: boolean;
  seconds?: number;
}
export interface StudioContent {
  schema: string;
  plaque: { text: string };
  rooms: { id: string; title: string; intro: { text: string; source: DcSource } }[];
  credits: { curatorNote: { text: string; source: DcSource }; highlights: StudioCard[]; frame: string };
  traces: StudioCard[];
  telegram: StudioCard;
  artViewer: StudioArt[];
  soundBooth: StudioSound[];
  workbench: { id: string; original: string; caption: string; source: DcSource; reconstructed?: boolean }[];
  index: { id: string; kind: string; title: string; reconstructed: boolean }[];
  studioNotes: { id: string; title: string; caption: string; source: DcSource; text?: string; a?: string; b?: string; path?: string }[];
}

const modules = import.meta.glob<unknown>(['../../content/devcut.json', '../../content/studio.json', '../../content/credits.json'], { import: 'default' });
const load = async <T>(name: string): Promise<T> => {
  const m = modules[`../../content/${name}`];
  if (!m) throw new Error(`devcut content missing: ${name} (run: bun tools/content/devcut.ts)`);
  return (await m()) as T;
};

let devcutP: Promise<DevcutContent> | null = null;
let studioP: Promise<StudioContent> | null = null;
export const loadDevcut = () => (devcutP ??= load<DevcutContent>('devcut.json'));
export const loadStudio = () => (studioP ??= load<StudioContent>('studio.json'));
export const loadCredits = () => load<{ text: string }>('credits.json');

/** Public URL for an asset path from the JSON (`assets/devcut/...`). */
export const assetUrl = (p: string) => `${import.meta.env.BASE_URL}${p}`;

/** Look up a Dev Cut text (letters, messages, captions). */
export function devcutText(dc: DevcutContent, id: string): DcText | null {
  return dc.texts[id] ?? null;
}

/** Fill the original placeholders: FIRSTNAME / [FIRSTNAME], <Son1>, <Name>. */
export function fillPlaceholders(text: string, p: { firstName?: string; son1?: string; name?: string }): string {
  let t = text;
  if (p.firstName) t = t.replace(/\[?FIRSTNAME\]?/g, p.firstName);
  if (p.son1) t = t.replace(/<Son1>/g, p.son1);
  if (p.name) t = t.replace(/<Name>/g, p.name);
  return t;
}
